        $job = Start-Job -ScriptBlock { param($path) Remove-Item -Path $path -Recurse -Force } -ArgumentList $k
        if ($job | Wait-Job -Timeout 5) {
            Receive-Job $job
        } else {
            Write-Warning "Timed out removing $k. It might be locked."
            Stop-Job $job
        }
        Remove-Job $job
    } else {
        # Standard fast removal
        Remove-Item -Path $k -Recurse -Force
    }
}
